<?php /* Template Name: Course catalogue */ get_header(); $direction = get_query_var('course_direction'); ?><main class="catalogue"><div class="container"><p class="eyebrow">Course catalogue</p><h1><?php the_title(); ?></h1><div class="catalogue-layout"><aside><?php foreach(get_terms(array('taxonomy'=>'course_direction','hide_empty'=>false)) as $term): ?><a href="<?php echo esc_url(get_term_link($term)); ?>"><?php echo esc_html($term->name); ?></a><?php endforeach; ?></aside><section class="course-grid"><?php $query = new WP_Query(array('post_type'=>'course','posts_per_page'=>-1,'course_direction'=>$direction)); while($query->have_posts()): $query->the_post(); ?><article><h2><?php the_title(); ?></h2><?php the_excerpt(); ?><a href="<?php the_permalink(); ?>">Course details →</a></article><?php endwhile; wp_reset_postdata(); ?></section></div></div></main><?php get_footer(); ?>
